      this.corps.localPosition = new Vector3(0, Math.abs(Math.sin(this.phase)) * 0.06 * k + Math.sin(Time.time * 3) * 0.015, 0);
      this.corps.localEulerAngles = new Vector3(0, 0, -7 * k);
